using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows.Forms;
namespace Aster {
public class PersonalTask {public string Title;public bool Done;public override string ToString(){return Title;}}
public class PersonalData {public int Version=1;public string Note="";public List<PersonalTask> Tasks=new List<PersonalTask>();}
static class PersonalStore {
 public static string FileName=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","PersonalWorkspace.json");
 public static void Validate(PersonalData data){if(data==null||data.Version!=1||data.Note==null||data.Note.Length>50000||data.Tasks==null||data.Tasks.Count>200||data.Tasks.Any(t=>t==null||string.IsNullOrWhiteSpace(t.Title)||t.Title.Length>300))throw new Exception("Invalid personal workspace file. The original file has been left untouched.");}
 public static PersonalData Read(){if(!File.Exists(FileName))return new PersonalData();if(new FileInfo(FileName).Length>1048576)throw new Exception("Personal workspace file exceeds 1 MB.");var data=new JavaScriptSerializer{MaxJsonLength=1048576}.Deserialize<PersonalData>(File.ReadAllText(FileName));Validate(data);return data;}
 public static void Save(PersonalData data){Validate(data);Directory.CreateDirectory(Path.GetDirectoryName(FileName));string temporary=FileName+".tmp";File.WriteAllText(temporary,new JavaScriptSerializer{MaxJsonLength=1048576}.Serialize(data),Encoding.UTF8);if(File.Exists(FileName))File.Replace(temporary,FileName,FileName+".backup");else File.Move(temporary,FileName);}
}
class QuickAction {public string Label;public Action Run;public override string ToString(){return Label;}}
partial class MainWindow {
 PersonalData personal=new PersonalData();bool personalDirty;string personalLoadError;PersonalTask removedTask;int removedTaskIndex;
 void SetupPersonalWorkspace(){try{personal=PersonalStore.Read();}catch(Exception ex){personalLoadError=ex.Message;}FormClosing+=(s,e)=>{if(!personalDirty)return;var answer=MessageBox.Show(this,"Save your notebook and checklist changes before closing?","Unsaved workspace",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Cancel)e.Cancel=true;else if(answer==DialogResult.Yes&&!SavePersonal())e.Cancel=true;};}
 bool SavePersonal(){try{if(personalLoadError!=null)throw new Exception(personalLoadError);PersonalStore.Save(personal);personalDirty=false;return true;}catch(Exception ex){MessageBox.Show(this,"Could not save: "+ex.Message);return false;}}
 void ExportPersonalText(string title,string data){using(var d=new SaveFileDialog{Filter="Text document|*.txt",FileName="Aster-"+title+".txt"})if(d.ShowDialog(this)==DialogResult.OK){try{File.WriteAllText(d.FileName,data,Encoding.UTF8);}catch(Exception ex){MessageBox.Show(this,ex.Message);}}}
 void BuildNotebook(){sub.Text="Your local scratchpad · keep troubleshooting notes, ideas and reminders";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,44));content.Controls.Add(root);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(actions,0,0);var editor=new TextBox{Multiline=true,AcceptsReturn=true,AcceptsTab=true,Dock=DockStyle.Fill,ScrollBars=ScrollBars.Vertical,MaxLength=50000,Font=new Font("Segoe UI",12),Text=personal.Note,ReadOnly=personalLoadError!=null};root.Controls.Add(editor,0,1);var state=new Label{Dock=DockStyle.Fill,Text=personalLoadError??"Local only · Save writes your notebook and checklist together."};root.Controls.Add(state,0,2);editor.TextChanged+=(s,e)=>{personal.Note=editor.Text;personalDirty=true;state.Text="Unsaved · "+editor.TextLength.ToString("N0")+" / 50,000 characters. Text stays while switching pages.";};var save=Button("Save workspace");save.Enabled=personalLoadError==null;save.Click+=(s,e)=>{if(SavePersonal())state.Text="Saved locally · "+DateTime.Now.ToString("T");};actions.Controls.Add(save);var export=Button("Export text");export.Click+=(s,e)=>ExportPersonalText("notes",editor.Text);actions.Controls.Add(export);var stamp=Button("Insert date & time");stamp.Enabled=personalLoadError==null;stamp.Click+=(s,e)=>{var date=preferences.RiyadhTime?DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(3)):DateTimeOffset.Now;editor.SelectedText="\r\n["+date.ToString("yyyy-MM-dd HH:mm zzz")+"] ";editor.Focus();};actions.Controls.Add(stamp);}
 void BuildChecklist(){sub.Text="A simple local checklist · changes survive page switches · save when ready";var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4};root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,44));content.Controls.Add(root);var inputRow=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(inputRow,0,0);var input=new TextBox{Width=480,MaxLength=300};inputRow.Controls.Add(input);var add=Button("Add task");add.Enabled=personalLoadError==null;inputRow.Controls.Add(add);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};root.Controls.Add(actions,0,1);var list=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,BorderStyle=BorderStyle.None,Font=new Font("Segoe UI",12),Enabled=personalLoadError==null};root.Controls.Add(list,0,2);var state=new Label{Dock=DockStyle.Fill};root.Controls.Add(state,0,3);var hide=new CheckBox{Text="Hide completed",AutoSize=true,Margin=new Padding(12,8,8,0)};bool filling=false;Action status=()=>state.Text=personalLoadError??(personal.Tasks.Count(t=>t.Done)+" / "+personal.Tasks.Count+" completed · "+(personalDirty?"unsaved changes":"saved")+" · up to 200 tasks");Action refresh=()=>{filling=true;list.Items.Clear();foreach(var task in personal.Tasks.Where(t=>!hide.Checked||!t.Done))list.Items.Add(task,task.Done);filling=false;status();};Action addTask=()=>{string title=input.Text.Trim();if(title.Length==0)return;if(personal.Tasks.Count>=200){MessageBox.Show(this,"This checklist supports up to 200 tasks.");return;}personal.Tasks.Add(new PersonalTask{Title=title});personalDirty=true;input.Clear();refresh();};add.Click+=(s,e)=>addTask();input.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter&&add.Enabled){e.SuppressKeyPress=true;addTask();}};list.ItemCheck+=(s,e)=>{if(filling)return;((PersonalTask)list.Items[e.Index]).Done=e.NewValue==CheckState.Checked;personalDirty=true;BeginInvoke(new Action(()=>{if(!list.IsDisposed){if(hide.Checked)refresh();else status();}}));};var save=Button("Save workspace");save.Enabled=personalLoadError==null;save.Click+=(s,e)=>{SavePersonal();status();};actions.Controls.Add(save);var remove=Button("Remove selected");remove.Click+=(s,e)=>{var selected=list.SelectedItem as PersonalTask;if(selected==null)return;removedTask=selected;removedTaskIndex=personal.Tasks.IndexOf(selected);personal.Tasks.Remove(selected);personalDirty=true;refresh();};actions.Controls.Add(remove);var undo=Button("Undo last removal");undo.Click+=(s,e)=>{if(removedTask==null||personal.Tasks.Count>=200)return;personal.Tasks.Insert(Math.Min(removedTaskIndex,personal.Tasks.Count),removedTask);removedTask=null;personalDirty=true;refresh();};actions.Controls.Add(undo);actions.Controls.Add(hide);hide.CheckedChanged+=(s,e)=>refresh();var export=Button("Export text");export.Click+=(s,e)=>ExportPersonalText("checklist",string.Join(Environment.NewLine,personal.Tasks.Select(t=>(t.Done?"[x] ":"[ ] ")+t.Title)));inputRow.Controls.Add(export);refresh();}
 void ShowActionLauncher(){var choices=new List<QuickAction>();foreach(string name in buttons.Keys){string target=name;choices.Add(new QuickAction{Label="Open · "+name,Run=()=>Navigate(target)});}choices.Add(new QuickAction{Label="Action · Pause / resume monitoring",Run=()=>{paused=!paused;pause.Text=paused?"Resume":"Pause";UpdateView();}});choices.Add(new QuickAction{Label="Action · Toggle distraction-free view",Run=ToggleFocusMode});choices.Add(new QuickAction{Label="Action · Change app picture now",Run=()=>SelectPicture(CurrentPictureNumber()+1)});choices.Add(new QuickAction{Label="Action · Save notebook and checklist",Run=()=>SavePersonal()});QuickAction chosen=null;using(var dialog=new Form{Text="Aster · Find a page or action",Size=new Size(590,520),StartPosition=FormStartPosition.CenterParent,BackColor=panel,ForeColor=Color.White,Font=Font,KeyPreview=true}){var searchBox=new TextBox{Dock=DockStyle.Top,Font=new Font("Segoe UI",14),BackColor=panel,ForeColor=Color.White};var list=new ListBox{Dock=DockStyle.Fill,BackColor=panel,ForeColor=Color.White,BorderStyle=BorderStyle.None};dialog.Controls.Add(list);dialog.Controls.Add(searchBox);Action refresh=()=>{list.Items.Clear();foreach(var action in choices.Where(a=>a.Label.IndexOf(searchBox.Text.Trim(),StringComparison.OrdinalIgnoreCase)>=0))list.Items.Add(action);if(list.Items.Count>0)list.SelectedIndex=0;};Action select=()=>{chosen=list.SelectedItem as QuickAction;if(chosen!=null)dialog.Close();};searchBox.TextChanged+=(s,e)=>refresh();searchBox.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;select();}else if(e.KeyCode==Keys.Down)list.Focus();};list.DoubleClick+=(s,e)=>select();list.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;select();}};dialog.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape)dialog.Close();};refresh();dialog.ShowDialog(this);}if(chosen!=null)try{chosen.Run();}catch(Exception ex){MessageBox.Show(this,ex.Message);}}
}
}

